'use client';

import React, { useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { REGULATORY_SEEDS } from '@/lib/momentum-data';

type View = 'overview'|'projects'|'groups'|'messages'|'documents'|'offers'|'roadmap'|'manufacturing'|'regulatory'|'integration'|'resources'|'tasks'|'meetings'|'notifications'|'settings';

const NAV:{group:string,items:{id:View,label:string,icon:string}[]}[]=[
 {group:'Workspace',items:[{id:'overview',label:'Overview',icon:'⌂'},{id:'projects',label:'Projects',icon:'▦'},{id:'groups',label:'Teams & Groups',icon:'◎'},{id:'messages',label:'Messages',icon:'✦'}]},
 {group:'Commercial',items:[{id:'offers',label:'Offers',icon:'€'},{id:'roadmap',label:'Roadmap',icon:'↗'},{id:'meetings',label:'Meetings',icon:'◫'},{id:'tasks',label:'Tasks',icon:'✓'}]},
 {group:'Operations',items:[{id:'manufacturing',label:'Manufacturing',icon:'⚙'},{id:'regulatory',label:'Regulatory Watch',icon:'◉'},{id:'integration',label:'Integration Lab',icon:'⌘'}]},
 {group:'Knowledge',items:[{id:'documents',label:'Files & Data Room',icon:'▤'},{id:'resources',label:'Certificates',icon:'◇'},{id:'notifications',label:'Notifications',icon:'●'}]},
];

const DEMO_MESSAGES=[
 {who:'Momentum Spain',role:'Integration',text:'Sandbox mapping for the V16 event model is ready for validation.',time:'09:18',mine:false},
 {who:'China Engineering',role:'DCT Invent',text:'Pilot PCB inspection completed. QA report uploaded to the manufacturing group.',time:'10:04',mine:false},
 {who:'Client Operations',role:'Fleet',text:'We have attached the first 50 vehicle identifiers for PoC mapping.',time:'10:21',mine:true},
 {who:'Regulatory Watch',role:'System',text:'RD 450/2026 review updated: NAP/SIT impact note added to the project.',time:'11:07',mine:false},
];

const DEMO_ROADMAP=[
 ['Discovery & owner mapping','completed','2026-09-18 09:00','Commercial'],
 ['Security / architecture workshop','completed','2026-09-22 11:30','Integration'],
 ['Read-only sandbox','in_progress','2026-09-30 10:00','Integration'],
 ['50-device PoC mapping','planned','2026-10-05 09:30','Operations'],
 ['Webhook acceptance test','planned','2026-10-09 15:00','Engineering'],
 ['Production readiness review','planned','2026-10-16 10:00','Governance'],
];

const DEMO_MFG=[
 ['Electronics BOM freeze','engineering','passed','Huizhou · CN','China Engineering'],
 ['Critical supplier review','supplier','passed','Guangdong · CN','Supply Chain'],
 ['Pilot lot incoming inspection','incoming','in_progress','Huizhou · CN','Quality'],
 ['Pilot assembly','pilot','planned','Huizhou · CN','Manufacturing'],
 ['Functional + connectivity QA','qa','planned','Huizhou · CN','Quality'],
 ['Packing / traceability release','packing','planned','Huizhou · CN','Logistics'],
];

const CERTS=[
 ['CE Certificate','CE / Conformity','NDA required'],
 ['RED Test Report','Radio Equipment Directive','NDA required'],
 ['RoHS Report','Restricted substances','NDA required'],
 ['REACH Report','Chemical compliance','NDA required'],
 ['IP54 Test','Environmental protection','NDA required'],
 ['EN 60598 Report 001','Product test report','NDA required'],
 ['EN 60598 Report 002','Product test report','NDA required'],
 ['IDIADA G001','V16 certification · PC25040022','Public / controlled copy'],
 ['IDIADA G002','V16 certification · PC25100427','Public / controlled copy'],
];

const INTEGRATION_STEPS=[
 ['01','Source','Partner backend · direct device · simulator'],
 ['02','Authenticate','API key / device or source identity'],
 ['03','Ingest','Schema validation · timestamp · idempotency'],
 ['04','Preserve','Raw payload + SHA-256 traceability'],
 ['05','Normalize','Momentum canonical event model'],
 ['06','Distribute','Read-only API + HMAC webhook'],
 ['07','Operate','Road Command · FMS · insurance · assistance'],
];

export default function WorkspaceApp(){
 const [view,setView]=useState<View>('overview');
 const [session,setSession]=useState<any>(null);
 const [loading,setLoading]=useState(true);
 const [email,setEmail]=useState('');
 const [magicSent,setMagicSent]=useState(false);
 const [org,setOrg]=useState<any>(null);
 const [onboard,setOnboard]=useState({company:'',name:'',title:''});
 const [legalOpen,setLegalOpen]=useState(false);
 const [legal,setLegal]=useState({privacy:false,nda:false});
 const [toast,setToast]=useState('');
 const [ndaDoc,setNdaDoc]=useState<string|null>(null);
 const [requested,setRequested]=useState<string[]>([]);
 const [channel,setChannel]=useState('Project room');
 const [msg,setMsg]=useState('');
 const [messages,setMessages]=useState(DEMO_MESSAGES);
 const [sidebar,setSidebar]=useState(true);
 const company=org?.name || onboard.company || 'Demo Mobility Group';

 useEffect(()=>{
   let mounted=true;
   supabase.auth.getSession().then(({data})=>{if(mounted){setSession(data.session); setLoading(false);}});
   const {data:sub}=supabase.auth.onAuthStateChange((_event,s)=>{setSession(s); if(!s)setOrg(null);});
   return()=>{mounted=false;sub.subscription.unsubscribe();}
 },[]);

 useEffect(()=>{ if(session?.user) loadAccount(); },[session?.user?.id]);

 async function loadAccount(){
   const {data:members}=await supabase.from('memberships').select('organization_id,role,organizations(*)').eq('user_id',session.user.id).limit(1);
   if(members?.length){
     const o=(members[0] as any).organizations; setOrg(o);
     const {data:acc}=await supabase.from('legal_acceptances').select('acceptance_type').eq('user_id',session.user.id).eq('organization_id',o.id);
     const have=new Set((acc||[]).map((x:any)=>x.acceptance_type));
     if(!have.has('privacy')||!have.has('nda')) setLegalOpen(true);
   }
 }

 async function sendMagic(){
   if(!email)return;
   const {error}=await supabase.auth.signInWithOtp({email,options:{emailRedirectTo:window.location.href.split('#')[0].split('?')[0]}});
   if(error){setToast(error.message);return;} setMagicSent(true);
 }

 async function doOnboard(){
   if(!onboard.company)return;
   const {data,error}=await supabase.rpc('onboard_company',{company_name:onboard.company,person_name:onboard.name||null,person_title:onboard.title||null});
   if(error){setToast(error.message);return;}
   const {data:o}=await supabase.from('organizations').select('*').eq('id',data).single();
   setOrg(o); setLegalOpen(true); setToast('Workspace creado para '+onboard.company);
 }

 async function acceptLegal(){
   if(!legal.privacy||!legal.nda||!session?.user||!org)return;
   const rows=[
     {organization_id:org.id,user_id:session.user.id,acceptance_type:'privacy',version:'2026.09',company_name_snapshot:org.name,user_agent:navigator.userAgent},
     {organization_id:org.id,user_id:session.user.id,acceptance_type:'nda',version:'2026.09',company_name_snapshot:org.name,user_agent:navigator.userAgent},
   ];
   const {error}=await supabase.from('legal_acceptances').upsert(rows,{onConflict:'user_id,organization_id,acceptance_type,version'});
   if(error){setToast(error.message);return;} setLegalOpen(false); setToast('Declaraciones registradas.');
 }

 async function requestDoc(name:string){
   if(!session?.user||!org){setRequested(x=>[...new Set([...x,name])]);setNdaDoc(null);setToast('Petición en curso. El documento aparecerá en Documentos recibidos.');return;}
   const {data:nda}=await supabase.from('legal_acceptances').select('id').eq('user_id',session.user.id).eq('organization_id',org.id).eq('acceptance_type','nda').limit(1).maybeSingle();
   await supabase.from('document_requests').insert({organization_id:org.id,requested_by:session.user.id,document_key:name.toLowerCase().replace(/\W+/g,'_'),document_title:name,status:nda?'processing':'nda_required',nda_acceptance_id:nda?.id||null});
   setRequested(x=>[...new Set([...x,name])]);setNdaDoc(null);setToast('Petición en curso. Verá el documento solicitado en su contenedor de Documentos recibidos.');
 }

 function sendMessage(){
   if(!msg.trim())return;
   setMessages(m=>[...m,{who:'You',role:'Client',text:msg.trim(),time:new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'}),mine:true}]);
   setMsg('');
 }

 if(loading) return <div className="ws-loading">MOMENTUM WORKSPACE<div/></div>;
 if(!session) return <LoginScreen email={email} setEmail={setEmail} sendMagic={sendMagic} sent={magicSent} />;
 if(!org) return <Onboarding value={onboard} setValue={setOnboard} submit={doOnboard}/>;

 return <div className="ws">
   <aside className={sidebar?'ws-side':'ws-side collapsed'}>
     <div className="ws-brand"><div className="ws-mark">M</div>{sidebar&&<div><strong>MOMENTUM</strong><span>WORKSPACE</span></div>}<button onClick={()=>setSidebar(!sidebar)}>☰</button></div>
     {NAV.map(g=><div className="ws-nav-group" key={g.group}>{sidebar&&<small>{g.group}</small>}{g.items.map(it=><button key={it.id} onClick={()=>setView(it.id)} className={view===it.id?'active':''}><i>{it.icon}</i>{sidebar&&<span>{it.label}</span>}</button>)}</div>)}
     <div className="ws-side-bottom"><div className="ws-env"><b>●</b>{sidebar&&<span>EU Workspace<br/><small>Supabase · RLS</small></span>}</div><button onClick={()=>supabase.auth.signOut()}>↪ {sidebar&&'Sign out'}</button></div>
   </aside>
   <div className="ws-main">
     <header className="ws-top">
       <div><span className="ws-crumb">Momentum / {company}</span><strong>{titleFor(view)}</strong></div>
       <div className="ws-top-actions"><div className="ws-search">⌕ <span>Search workspace</span><kbd>⌘K</kbd></div><button onClick={()=>setView('notifications')} className="ws-bell">●<em>3</em></button><div className="ws-avatar">{initials(session.user.email||'CL')}</div></div>
     </header>
     <div className="ws-content">
       {view==='overview'&&<Overview company={company} go={setView}/>}
       {view==='projects'&&<Projects/>}
       {view==='groups'&&<Groups org={org}/>}
       {view==='messages'&&<Messages org={org} user={session.user}/>}
       {view==='documents'&&<Documents requested={requested} org={org} user={session.user}/>}
       {view==='offers'&&<Offers/>}
       {view==='roadmap'&&<Roadmap/>}
       {view==='manufacturing'&&<Manufacturing/>}
       {view==='regulatory'&&<Regulatory/>}
       {view==='integration'&&<IntegrationLab/>}
       {view==='resources'&&<Resources requested={requested} request={(n:string)=>setNdaDoc(n)}/>}
       {view==='tasks'&&<Tasks/>}
       {view==='meetings'&&<Meetings/>}
       {view==='notifications'&&<Notifications/>}
       {view==='settings'&&<Settings company={company}/>}
     </div>
   </div>
   {legalOpen&&<LegalModal company={company} legal={legal} setLegal={setLegal} accept={acceptLegal}/>}
   {ndaDoc&&<NdaRequest doc={ndaDoc} company={company} cancel={()=>setNdaDoc(null)} request={()=>requestDoc(ndaDoc)}/>}
   {toast&&<div className="ws-toast" onAnimationEnd={()=>setTimeout(()=>setToast(''),3500)}>{toast}</div>}
 </div>
}

function LoginScreen({email,setEmail,sendMagic,sent}:any){return <div className="ws-auth"><div className="ws-auth-panel"><div className="ws-auth-brand"><div className="ws-mark">M</div><b>MOMENTUM SYSTEMS</b></div><span className="ey">SECURE CLIENT WORKSPACE</span><h1>Projects, people and evidence in one place.</h1><p>Secure collaboration from technical evaluation to manufacturing, regulatory follow-up, integration and ongoing service.</p>{sent?<div className="ws-auth-success">Check your email. We sent a secure sign-in link.</div>:<><label>Work email</label><input value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@company.com"/><button onClick={sendMagic}>Continue securely →</button></>}<small>Access is logged. Documents and certificates can be subject to NDA and project permissions.</small></div><div className="ws-auth-visual"><div className="auth-orb"><b>M</b></div><div className="auth-line"/><span>SPAIN</span><span>CHINA ENGINEERING</span><span>CLIENT TEAM</span></div></div>}
function Onboarding({value,setValue,submit}:any){return <div className="ws-auth"><div className="ws-auth-panel"><span className="ey">ONBOARDING</span><h1>Create your company workspace.</h1><p>This company name is also used to personalise the NDA and privacy declaration shown on first entry.</p><label>Company / legal entity</label><input value={value.company} onChange={e=>setValue({...value,company:e.target.value})}/><div className="ws-form-row"><div><label>Your name</label><input value={value.name} onChange={e=>setValue({...value,name:e.target.value})}/></div><div><label>Role</label><input value={value.title} onChange={e=>setValue({...value,title:e.target.value})}/></div></div><button onClick={submit}>Create workspace →</button></div><div className="ws-auth-visual"><div className="onboard-list">{['Private tenant','Role-based access','Project groups','Secure documents','Regulatory watch','Spain ↔ China collaboration'].map(x=><div key={x}>✓ {x}</div>)}</div></div></div>}

function Overview({company,go}:any){return <><div className="ws-page-head"><div><span>Good afternoon</span><h1>{company}</h1><p>One workspace for commercial, technical, manufacturing and compliance progress.</p></div><button className="ws-red" onClick={()=>go('integration')}>Open Integration Lab</button></div><div className="ws-kpis">{[['Project health','ON TRACK','green'],['Current stage','SANDBOX','blue'],['Open actions','7',''],['Unread messages','4','red'],['Regulatory alerts','2','yellow'],['Documents pending','3','']].map(([a,b,c])=><div key={a}><span>{a}</span><strong className={c}>{b}</strong><small>Updated today</small></div>)}</div><div className="ws-two"><section className="ws-card"><CardHead title="Project activity" action="View roadmap" onClick={()=>go('roadmap')}/><div className="ws-activity">{DEMO_ROADMAP.slice(0,5).map(([t,s,time,l])=><div key={t}><i className={s}/><span><b>{t}</b><small>{l} · {time}</small></span><em>{s.replace('_',' ')}</em></div>)}</div></section><section className="ws-card"><CardHead title="Collaboration rooms" action="Open groups" onClick={()=>go('groups')}/>{[['Spain · Client Core Team','8 members','Commercial + technical'],['China Manufacturing','6 members','Engineering + QA + supplier'],['Regulatory & Compliance','5 members','MITMA · DGT · CE · RoHS'],['Integration Room','7 members','API · webhook · FMS']].map(x=><div className="ws-room" key={x[0]}><div className="room-avatars"><i/><i/><i/></div><span><b>{x[0]}</b><small>{x[2]}</small></span><em>{x[1]}</em></div>)}</section></div><div className="ws-three"><Mini title="Next meeting" big="Architecture review" text="Tue · 11:00 CET · 6 participants"/><Mini title="Latest offer" big="MS-2026-014" text="Issued · awaiting customer review"/><Mini title="Manufacturing" big="Pilot inspection" text="In progress · Huizhou, Guangdong"/></div></>}
function Projects(){return <Page title="Projects" sub="A single view from discovery to production."><div className="ws-project-hero"><div><span>ACTIVE PROJECT</span><h2>Connected Event Integration</h2><p>Read-only event sandbox, webhook validation and initial vehicle/device mapping.</p><div className="ws-mini-tags"><b>Sandbox</b><b>Insurance/Fleet</b><b>Spain</b><b>China support</b></div></div><div className="proj-score"><strong>68%</strong><span>PoC readiness</span></div></div><div className="ws-section-title">Stage gates</div><div className="stage-gates">{['Discovery','Architecture','Sandbox','PoC','Contracting','Production'].map((x,i)=><div className={i<3?'done':i===3?'active':''} key={x}><i>{i<3?'✓':i+1}</i><span>{x}</span></div>)}</div></Page>}
function Groups({org}:any){
 const base=[['Spain · Client Core','project','Momentum Spain · Customer PM · IT'],['China Manufacturing','manufacturing','DCT Invent · QA · Factory · Supply chain'],['Regulatory & Compliance','regulatory','Spain regulatory · China EHS · Product'],['Integration Engineering','integration','Backend · API · Webhook · Customer FMS'],['Quality Review','quality','QA · Certification · Customer quality'],['Executive Steering','project','Decision makers · milestones · offers']];
 const [groups,setGroups]=useState<any[]>(base);
 const [name,setName]=useState('');
 const [type,setType]=useState('project');
 useEffect(()=>{if(!org?.id)return;supabase.from('collaboration_groups').select('id,name,group_type,description').eq('organization_id',org.id).order('created_at').then(({data})=>{if(data?.length)setGroups(data.map((x:any)=>[x.name,x.group_type,x.description||'Project collaboration group',x.id]));});},[org?.id]);
 async function create(){
  if(!name.trim())return;
  const row={organization_id:org.id,name:name.trim(),group_type:type,description:'Created from Momentum Workspace'};
  const {data,error}=await supabase.from('collaboration_groups').insert(row).select().single();
  if(!error&&data){setGroups(g=>[[data.name,data.group_type,data.description,data.id],...g]);setName('');}
 }
 return <Page title="Teams & Groups" sub="Create project rooms that join customer, Spain and China responsibilities."><div className="group-create"><input value={name} onChange={e=>setName(e.target.value)} placeholder="New group name"/><select value={type} onChange={e=>setType(e.target.value)}><option value="project">Project</option><option value="manufacturing">Manufacturing</option><option value="quality">Quality</option><option value="regulatory">Regulatory</option><option value="integration">Integration</option><option value="commercial">Commercial</option></select><button className="ws-red" onClick={create}>＋ Create group</button></div><div className="group-grid">{groups.map((g,i)=><div className="group-card" key={(g[3]||g[0])}><div className={'group-icon g'+(i%5)}>◎</div><span>{g[1]}</span><h3>{g[0]}</h3><p>{g[2]}</p><div className="group-foot"><div className="room-avatars"><i/><i/><i/><i/></div><button>Open room →</button></div></div>)}</div></Page>}
function Messages({org,user}:any){
 const [rooms,setRooms]=useState<any[]>([]);
 const [active,setActive]=useState<any>(null);
 const [items,setItems]=useState<any[]>([]);
 const [text,setText]=useState('');
 useEffect(()=>{
   if(!org?.id)return;
   supabase.from('channels').select('*').eq('organization_id',org.id).order('created_at')
    .then(({data})=>{const r=data||[];setRooms(r);if(r.length)setActive((a:any)=>a||r[0]);});
 },[org?.id]);
 useEffect(()=>{
   if(!active?.id)return;
   let alive=true;
   supabase.from('channel_messages').select('*').eq('channel_id',active.id).order('created_at',{ascending:true}).limit(150)
    .then(({data})=>{if(alive)setItems(data||[])});
   const ch=supabase.channel('room:'+active.id)
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'channel_messages',filter:'channel_id=eq.'+active.id},(payload:any)=>{
      setItems(x=>x.some((m:any)=>m.id===payload.new.id)?x:[...x,payload.new]);
    }).subscribe();
   return()=>{alive=false;supabase.removeChannel(ch)};
 },[active?.id]);
 async function send(){
   const body=text.trim(); if(!body||!active?.id||!org?.id)return;
   setText('');
   const {error}=await supabase.from('channel_messages').insert({
     channel_id:active.id,organization_id:org.id,author_id:user?.id||null,body,message_type:'message'
   });
   if(error)setText(body);
 }
 const demo=items.length?items:DEMO_MESSAGES.map((m:any,i:number)=>({id:'demo-'+i,body:m.text,author_id:m.mine?user?.id:null,created_at:new Date().toISOString(),demo_name:m.who,demo_role:m.role}));
 return <Page title="Messages" sub="Persistent project communication by room, responsibility and decision context.">
  <div className="chat-layout">
   <aside><input placeholder="Search conversations"/>{(rooms.length?rooms:[{id:'demo-1',name:'Project room'},{id:'demo-2',name:'Sales ↔ Client'},{id:'demo-3',name:'China Manufacturing'},{id:'demo-4',name:'Regulatory'},{id:'demo-5',name:'Integration Lab'}]).map((r:any)=><button key={r.id} onClick={()=>rooms.length&&setActive(r)} className={(active?.id===r.id||(!active&&r.name==='Project room'))?'active':''}><i>●</i><span><b>{r.name}</b><small>{r.channel_type||'Project channel'}</small></span></button>)}</aside>
   <section className="chat-main"><header><div><b>{active?.name||'Project room'}</b><small>Secure project channel · realtime enabled</small></div><button>⋯</button></header>
    <div className="chat-scroll">{demo.map((m:any)=><div className={m.author_id===user?.id?'chat-msg mine':'chat-msg'} key={m.id}><div className="msg-avatar">{initials(m.author_id===user?.id?'You':(m.demo_name||'Project participant'))}</div><div><span><b>{m.author_id===user?.id?'You':(m.demo_name||'Project participant')}</b><small>{m.demo_role||'Workspace member'} · {new Date(m.created_at).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}</small></span><p>{m.body}</p></div></div>)}</div>
    <div className="chat-compose"><button>＋</button><input value={text} onChange={e=>setText(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder={'Message '+(active?.name||'project room')}/><button onClick={send} className="send">Send</button></div>
   </section>
   <aside className="chat-info"><b>Room context</b><p>Messages stay attached to the project and are protected by tenant-level access controls.</p><span>Typical participants</span>{['Momentum Spain','Client PM','China Engineering','Quality','Regulatory'].map(x=><div key={x}><i/> {x}</div>)}</aside>
  </div>
 </Page>
}
function Documents({requested,org,user}:any){
 const [files,setFiles]=useState<any[]>([]);
 const [busy,setBusy]=useState(false);
 const [search,setSearch]=useState('');
 useEffect(()=>{
  if(!org?.id)return;
  supabase.from('documents').select('*').eq('organization_id',org.id).order('created_at',{ascending:false}).limit(30)
   .then(({data})=>setFiles(data||[]));
 },[org?.id]);
 async function upload(ev:any){
  const file=ev.target.files?.[0]; if(!file||!org?.id)return;
  setBusy(true);
  const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');
  const path=org.id+'/client_uploads/'+Date.now()+'_'+safe;
  const {error}=await supabase.storage.from('client-documents').upload(path,file,{upsert:false});
  if(!error){
   const {data}=await supabase.from('documents').insert({
    organization_id:org.id,title:file.name,document_type:'client_upload',storage_path:path,
    visibility:'client_upload',version_label:'v1',status:'available',uploaded_by:user?.id||null
   }).select().single();
   if(data)setFiles((x:any[])=>[data,...x]);
  }
  setBusy(false); ev.target.value='';
 }
 const visible=files.filter((x:any)=>!search||x.title.toLowerCase().includes(search.toLowerCase()));
 const rows=visible.length?visible.map((x:any)=>[x.title,x.document_type,x.version_label||'—',x.visibility,new Date(x.created_at).toLocaleString('es-ES')]):[
  ['API_Event_Model_v1.3.pdf','technical','v1.3','shared','Demo'],
  ['Pilot_QA_Checklist.xlsx','quality','v0.8','shared','Demo'],
  ...requested.map((x:string)=>[x,'certificate','Requested','processing','Now'])
 ];
 return <Page title="Files & Data Room" sub="Shared folders, customer uploads, received documents and version-controlled evidence.">
  <div className="doc-toolbar">
   <label className="ws-red upload-label">{busy?'Uploading…':'＋ Upload file'}<input type="file" hidden disabled={busy} onChange={upload}/></label>
   <button>New folder</button><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search files"/>
  </div>
  <div className="doc-folders">{[['01 · Commercial','Shared'],['02 · Technical analysis','Shared'],['03 · Integration','Shared'],['04 · Manufacturing & QA','Controlled'],['05 · Regulatory','Controlled'],['06 · Documents received','Private']].map((x,i)=><div key={x[0]}><div className="folder-icon">▰</div><span><b>{x[0]}</b><small>{i===5?(requested.length+' requested · '):''}{x[1]}</small></span><button>⋯</button></div>)}</div>
  <div className="ws-card"><CardHead title="Recent files" action="View all"/><DataTable cols={['Document','Type','Version','Access','Updated']} rows={rows}/></div>
 </Page>
}
