function IntegrationLab(){const [run,setRun]=useState(false);return <Page title="Integration Lab" sub="The full enterprise version of Momentum’s public event-flow story."><div className="int-hero"><div><span>ENVIRONMENT · SANDBOX</span><h2>Device event → enterprise action</h2><p>Generate a controlled event and follow authentication, raw preservation, normalization, signed delivery and operational visibility.</p><button className="ws-red" onClick={()=>{setRun(false);setTimeout(()=>setRun(true),30)}}>▶ Generate V16 test event</button></div><div className="int-health"><i/> API healthy<br/><i/> Webhook worker healthy<br/><i/> Demo devices online</div></div><div className="int-pipeline">{INTEGRATION_STEPS.map((s,i)=><div key={s[0]} className={run?'running':''} style={{animationDelay:(i*180)+'ms'}}><b>{s[0]}</b><span><strong>{s[1]}</strong><small>{s[2]}</small></span>{i<INTEGRATION_STEPS.length-1&&<em>→</em>}</div>)}</div><div className="ws-two"><section className="ws-card code-card"><CardHead title="Canonical event" action="Copy JSON"/><pre>{JSON.stringify({event_id:'evt_demo_20260930_001',event_type:'v16.activated',source_type:'instaflash_v16',device_id:'G001-DEMO-014',event_time:'2026-09-30T11:42:18Z',location:{lat:40.4168,lng:-3.7038},priority:'high',status:'active',schema_version:'1.0'},null,2)}</pre></section><section className="ws-card"><CardHead title="Delivery trace" action="Open logs"/>{[['Raw event stored','SHA-256 · immutable reference','PASS'],['Normalized','schema v1.0','PASS'],['REST API','GET /api/v1/events/...','200'],['Webhook signed','HMAC-SHA256','PASS'],['Customer endpoint','62 ms · DEMO','200']].map(x=><div className="delivery-row" key={x[0]}><span><b>{x[0]}</b><small>{x[1]}</small></span><em>{x[2]}</em></div>)}</section></div><div className="ws-card"><CardHead title="Deployment gates" action="Open technical room"/><DataTable cols={['Gate','Owner','Evidence','Status']} rows={[['Source authentication','Momentum Engineering','Source credential model','READY'],['Event schema','Momentum + Client','Canonical v1.0','READY'],['Webhook verification','Client IT','HMAC test','IN TEST'],['Security review','Both','Checklist / DPA','PLANNED'],['Production cutover','Both','Runbook + rollback','LOCKED']]}/></div></Page>}
function Resources({requested,request}:any){
 const [catalog,setCatalog]=useState<any[]>([]);
 const [filter,setFilter]=useState('All');
 useEffect(()=>{
  supabase.from('resource_catalog').select('*').eq('active',true).order('category')
   .then(({data})=>{if(data?.length)setCatalog(data)});
 },[]);
 const source=catalog.length?catalog:CERTS.map((x:any,i:number)=>({
  id:i,title:x[0],category:x[1],
  access_level:x[2].toLowerCase().includes('nda')?'nda_required':'controlled',
  product:x[0].includes('G002')?'Instaflash G002':'Instaflash G001'
 }));
 const categories=['All',...Array.from(new Set(source.map((x:any)=>x.category)))];
 const visible=source.filter((x:any)=>filter==='All'||x.category===filter);
 return <Page title="Certificates & Technical Resources" sub="Controlled access to certification, compliance and engineering evidence.">
  <div className="resource-banner"><div><span>CONTROLLED RESOURCE VAULT</span><h2>Evidence when your project needs it.</h2><p>Public certificates remain easy to identify. Detailed test reports and compliance evidence are released through the workspace under project permissions and, where applicable, NDA acknowledgement.</p></div><div className="vault-stat"><strong>{source.length}</strong><span>indexed resources</span></div></div>
  <div className="reg-tabs resource-tabs">{categories.slice(0,7).map((x:any)=><button className={filter===x?'active':''} onClick={()=>setFilter(x)} key={x}>{x}</button>)}</div>
  <div className="resource-grid">{visible.map((x:any)=><article key={x.id||x.title}><div className="pdf-icon">PDF</div><span>{x.category}</span><h3>{x.title}</h3><p>{x.product||'Momentum Systems'} · {x.access_level==='nda_required'?'NDA required':x.access_level}</p>{requested.includes(x.title)?<button className="requested">REQUEST IN PROGRESS</button>:<button onClick={()=>request(x.title)}>Request access →</button>}</article>)}</div>
 </Page>
}
